"""Train-time validation of builder-defined hooks."""

from __future__ import annotations

import ast
import inspect
from pathlib import Path
from typing import get_type_hints

from rasa.mantle.hooks.exceptions import (
    DuplicateModifierError,
    HookLoadingError,
    HookRejection,
    RetryModel,
)
from rasa.mantle.hooks.loader import iter_hook_module_paths, load_hooks
from rasa.mantle.hooks.points import HOOK_POINT_SPECS, spec_for_point
from rasa.mantle.hooks.types import MODIFY_LANE, OBSERVE_LANE
from rasa.mantle.validation_finding import ValidationFinding

_UNKNOWN_POINT_CODE = "mantle.validation.hooks.unknown_point"
_DUPLICATE_MODIFIER_CODE = "mantle.validation.hooks.duplicate_modifier"
_NON_ASYNC_CODE = "mantle.validation.hooks.non_async_handler"
_BAD_SIGNATURE_CODE = "mantle.validation.hooks.invalid_signature"
_UNSUPPORTED_CONTROL_CODE = "mantle.validation.hooks.unsupported_control_signal"
_IMPORT_FAILED_CODE = "mantle.validation.hooks.import_failed"

_CONTROL_SIGNAL_NAMES: tuple[tuple[str, type], ...] = (
    ("HookRejection", HookRejection),
    ("RetryModel", RetryModel),
)


def _validate_signature(func: object, *, point: str, lane: str) -> str | None:
    func_name = getattr(func, "__name__", repr(func))
    if not inspect.iscoroutinefunction(func):
        return f"{func_name!r} must be declared with async def."

    signature = inspect.signature(func)
    params = list(signature.parameters.values())
    if len(params) != 1:
        return (
            f"{func_name!r} must accept exactly one payload argument; "
            f"got {len(params)} parameter(s)."
        )

    payload_type = spec_for_point(point).payload_type
    try:
        hints = get_type_hints(func)
    except (NameError, TypeError, AttributeError) as exc:
        return f"{func_name!r} has annotations that could not be resolved: {exc}."

    param_name = params[0].name
    annotation = hints.get(param_name, inspect.Parameter.empty)
    if annotation is inspect.Parameter.empty:
        return (
            f"{func_name!r} must annotate its payload parameter with "
            f"{payload_type.__name__}."
        )
    if annotation is not payload_type:
        return (
            f"{func_name!r} must accept {payload_type.__name__}, "
            f"not {getattr(annotation, '__name__', annotation)!r}."
        )

    return_annotation = hints.get("return", inspect.Signature.empty)
    if lane == OBSERVE_LANE:
        if return_annotation not in (inspect.Signature.empty, type(None)):
            return f"{func_name!r} is an observe hook and must return None."
    elif return_annotation is not payload_type:
        return (
            f"{func_name!r} must return {payload_type.__name__}, "
            f"not {getattr(return_annotation, '__name__', return_annotation)!r}."
        )
    return None


def _parse_hook_module(module_path: Path) -> ast.AST | ValidationFinding:
    try:
        source = module_path.read_text(encoding="utf-8")
        return ast.parse(source, filename=str(module_path))
    except (OSError, UnicodeDecodeError, SyntaxError) as exc:
        return ValidationFinding(
            code=_IMPORT_FAILED_CODE,
            message=f"{module_path}: {exc}",
        )


def _unsupported_control_signals(
    tree: ast.AST,
    *,
    point: str,
    func_name: str,
) -> list[str]:
    allowed = spec_for_point(point).allowed_control_signals
    problems: list[str] = []

    for node in ast.walk(tree):
        if not isinstance(node, ast.AsyncFunctionDef) or node.name != func_name:
            continue
        for child in ast.walk(node):
            if not isinstance(child, ast.Raise) or child.exc is None:
                continue
            callee = child.exc.func if isinstance(child.exc, ast.Call) else child.exc
            if not isinstance(callee, ast.Name):
                continue
            for name, signal_type in _CONTROL_SIGNAL_NAMES:
                if callee.id == name and signal_type not in allowed:
                    problems.append(
                        f"{func_name!r} raises {name} at point {point!r}, "
                        "which does not allow that control signal."
                    )
    return problems


def _import_failure_already_reported(
    findings: list[ValidationFinding], load_message: str
) -> bool:
    """True when *load_message* is about a path already recorded as import_failed."""
    for finding in findings:
        if finding.code != _IMPORT_FAILED_CODE:
            continue
        reported_path = finding.message.split(": ", 1)[0]
        if reported_path and reported_path in load_message:
            return True
    return False


def validate_hooks(project_root: Path) -> list[ValidationFinding]:
    """Validate hook modules under the project root."""
    project_root = Path(project_root)
    findings: list[ValidationFinding] = []
    parsed_modules: dict[str, ast.AST] = {}

    for module_path in iter_hook_module_paths(project_root):
        parsed = _parse_hook_module(module_path)
        if isinstance(parsed, ValidationFinding):
            findings.append(parsed)
            continue
        parsed_modules[str(module_path)] = parsed

    try:
        registry = load_hooks(project_root)
    except (HookLoadingError, DuplicateModifierError) as exc:
        skip_duplicate_import = isinstance(
            exc, HookLoadingError
        ) and _import_failure_already_reported(findings, str(exc))
        if not skip_duplicate_import:
            findings.append(
                ValidationFinding(
                    code=_IMPORT_FAILED_CODE
                    if isinstance(exc, HookLoadingError)
                    else _DUPLICATE_MODIFIER_CODE,
                    message=str(exc),
                )
            )
        return findings

    for hook in registry.all_hooks():
        point = hook.point
        lane = hook.lane

        if point not in HOOK_POINT_SPECS:
            findings.append(
                ValidationFinding(
                    code=_UNKNOWN_POINT_CODE,
                    message=(
                        f"{hook.module_path}: hook {hook.func.__name__!r} "
                        f"registers unknown point {point!r}."
                    ),
                )
            )
            continue

        if not inspect.iscoroutinefunction(hook.func):
            findings.append(
                ValidationFinding(
                    code=_NON_ASYNC_CODE,
                    message=(
                        f"{hook.module_path}: hook {hook.func.__name__!r} "
                        "must be async."
                    ),
                )
            )
        else:
            signature_problem = _validate_signature(hook.func, point=point, lane=lane)
            if signature_problem is not None:
                findings.append(
                    ValidationFinding(
                        code=_BAD_SIGNATURE_CODE,
                        message=f"{hook.module_path}: {signature_problem}",
                    )
                )

        tree = parsed_modules.get(hook.module_path or "")
        if lane == MODIFY_LANE and tree is not None:
            for message in _unsupported_control_signals(
                tree,
                point=point,
                func_name=hook.func.__name__,
            ):
                findings.append(
                    ValidationFinding(
                        code=_UNSUPPORTED_CONTROL_CODE,
                        message=f"{hook.module_path}: {message}",
                    )
                )

    return findings
